 10→
 11→// GetTasks returns active tasks, optionally filtered.
 12→func (c *Client) GetTasks(projectID, filter string) ([]models.Task, error) {
 13→	endpoint := "/tasks"
 14→	var params []string
 15→	if projectID != "" {
 16→		params = append(params, fmt.Sprintf("project_id=%s", projectID))
 17→	}
 18→	if filter != "" {
 19→		params = append(params, fmt.Sprintf("filter=%s", filter))
 20→	}
 21→	if len(params) > 0 {
 22→		endpoint += "?" + strings.Join(params, "&")
 23→	}
 24→
 25→	data, err := c.do("GET", endpoint, nil)
 26→	if err != nil {
 27→		return nil, err
 28→	}
 29→
 30→	var page PaginatedResponse[models.Task]
 31→	if err := json.Unmarshal(data, &page); err != nil {
 32→		return nil, fmt.Errorf("failed to parse tasks: %w", err)
 33→	}
 34→	return page.Results, nil
 35→}
 36→
 37→// GetTask returns a single task by ID.
 38→func (c *Client) GetTask(id string) (*models.Task, error) {
 39→	data, err := c.do("GET", "/tasks/"+id, nil)
 40→	if err != nil {
 41→		return nil, err
 42→	}
 43→
 44→	var task models.Task
 45→	if err := json.Unmarshal(data, &task); err != nil {
 46→		return nil, fmt.Errorf("failed to parse task: %w", err)
 47→	}
 48→	return &task, nil
 49→}
 50→
 51→// CreateTask creates a new task.
 52→func (c *Client) CreateTask(body map[string]any) (*models.Task, error) {
 53→	data, err := c.do("POST", "/tasks", body)
 54→	if err != nil {
 55→		return nil, err
 56→	}
 57→
 58→	var task models.Task
 59→	if err := json.Unmarshal(data, &task); err != nil {
 60→		return nil, fmt.Errorf("failed to parse task: %w", err)
 61→	}
 62→	return &task, nil
 63→}
 64→
 65→// UpdateTask updates an existing task.
 66→func (c *Client) UpdateTask(id string, body map[string]any) (*models.Task, error) {
 67→	data, err := c.do("POST", "/tasks/"+id, body)
 68→	if err != nil {
 69→		return nil, err
 70→	}
 71→
 72→	var task models.Task
 73→	if err := json.Unmarshal(data, &task); err != nil {
 74→		return nil, fmt.Errorf("failed to parse task: %w", err)
 75→	}
 76→	return &task, nil
 77→}
 78→
 79→// DeleteTask deletes a task.
 80→func (c *Client) DeleteTask(id string) error {
 81→	_, err := c.do("DELETE", "/tasks/"+id, nil)
 82→	return err
 83→}
 84→
 85→// CloseTask marks a task as complete.
 86→func (c *Client) CloseTask(id string) error {
 87→	_, err := c.do("POST", "/tasks/"+id+"/close", nil)
 88→	return err
 89→}
 90→
 91→// ReopenTask reopens a completed task.
 92→func (c *Client) ReopenTask(id string) error {
 93→	_, err := c.do("POST", "/tasks/"+id+"/reopen", nil)
 94→	return err
 95→}
 96→
 97→// FindTaskByName searches for a task by partial name matching.
 98→// Returns nil if no match is found.
 99→func (c *Client) FindTaskByName(name string) (*models.Task, error) {
100→	tasks, err := c.GetTasks("", "")
101→	if err != nil {
102→		return nil, err
103→	}
104→
105→	nameLower := strings.ToLower(name)
106→
107→	// Prefer exact match first.
108→	for i := range tasks {
109→		if strings.ToLower(tasks[i].Content) == nameLower {
110→			return &tasks[i], nil
111→		}
112→	}
113→
114→	// Fall back to partial match.
115→	for i := range tasks {
116→		if strings.Contains(strings.ToLower(tasks[i].Content), nameLower) {
117→			return &tasks[i], nil
118→		}
119→	}
120→
121→	return nil, nil
122→}
