 12→// --- Input / Output types ---
 13→
 14→type CreateTaskInput struct {
 15→	Content     string   `json:"content" jsonschema:"The content/title of the task"`
 16→	Description string   `json:"description,omitempty" jsonschema:"Detailed description of the task (optional)"`
 17→	DueString   string   `json:"due_string,omitempty" jsonschema:"Natural language due date like 'tomorrow', 'next Monday', 'Jan 23' (optional)"`
 18→	Priority    int      `json:"priority,omitempty" jsonschema:"Task priority from 1 (normal) to 4 (urgent) (optional)"`
 19→	ProjectID   string   `json:"project_id,omitempty" jsonschema:"Project ID to create the task in (optional)"`
 20→	SectionID   string   `json:"section_id,omitempty" jsonschema:"Section ID to create the task in (optional)"`
 21→	ParentID    string   `json:"parent_id,omitempty" jsonschema:"Parent task ID for sub-tasks (optional)"`
 22→	Labels      []string `json:"labels,omitempty" jsonschema:"Labels to apply to the task (optional)"`
 23→	AssigneeID  string   `json:"assignee_id,omitempty" jsonschema:"User ID to assign the task to (optional)"`
 24→}
 25→
 26→type CreateTaskOutput struct {
 27→	Success bool   `json:"success"`
 28→	Message string `json:"message"`
 29→}
 30→
 31→type GetTasksInput struct {
 32→	ProjectID string `json:"project_id,omitempty" jsonschema:"Filter tasks by project ID (optional)"`
 33→	Filter    string `json:"filter,omitempty" jsonschema:"Natural language filter like 'today', 'tomorrow', 'next week', 'priority 1', 'overdue' (optional)"`
 34→	Priority  int    `json:"priority,omitempty" jsonschema:"Filter by priority level (1-4) (optional)"`
 35→	Limit     int    `json:"limit,omitempty" jsonschema:"Maximum number of tasks to return (optional, default 10)"`
 36→}
 37→
 38→type GetTasksOutput struct {
 39→	Success bool   `json:"success"`
 40→	Message string `json:"message"`
 41→}
 42→
 43→type UpdateTaskInput struct {
 44→	TaskID      string   `json:"task_id,omitempty" jsonschema:"Task ID to update (preferred over task_name)"`
 45→	TaskName    string   `json:"task_name,omitempty" jsonschema:"Name/content of the task to search for and update"`
 46→	Content     string   `json:"content,omitempty" jsonschema:"New content/title for the task (optional)"`
 47→	Description string   `json:"description,omitempty" jsonschema:"New description for the task (optional)"`
 48→	DueString   string   `json:"due_string,omitempty" jsonschema:"New due date in natural language (optional)"`
 49→	Priority    int      `json:"priority,omitempty" jsonschema:"New priority level from 1 (normal) to 4 (urgent) (optional)"`
 50→	Labels      []string `json:"labels,omitempty" jsonschema:"New labels for the task (optional)"`
 51→	AssigneeID  string   `json:"assignee_id,omitempty" jsonschema:"User ID to assign the task to (optional)"`
 52→}
