 89→// --- helpers ---
 90→
 91→func resolveTaskID(c *todoist.Client, id, name string) (string, string, error) {
 92→	if id != "" {
 93→		return id, "", nil
 94→	}
 95→	if name == "" {
 96→		return "", "", fmt.Errorf("either task_id or task_name is required")
 97→	}
 98→	task, err := c.FindTaskByName(name)
 99→	if err != nil {
100→		return "", "", err
101→	}
102→	if task == nil {
103→		return "", "", nil // not found
104→	}
105→	return task.ID, task.Content, nil
106→}
107→
108→func textResult(msg string, isError bool) *mcp.CallToolResult {
109→	return &mcp.CallToolResult{
110→		Content: []mcp.Content{&mcp.TextContent{Text: msg}},
111→		IsError: isError,
112→	}
113→}
