115→// --- registrations ---
116→
117→func registerTaskTools(s *mcp.Server, c *todoist.Client) {
118→	mcp.AddTool(s, &mcp.Tool{
119→		Name:        "todoist_create_task",
120→		Description: "Create a new task in Todoist with optional description, due date, priority, project, section, labels, and assignee",
121→	}, func(ctx context.Context, req *mcp.CallToolRequest, input CreateTaskInput) (*mcp.CallToolResult, CreateTaskOutput, error) {
122→		body := map[string]any{"content": input.Content}
123→		if input.Description != "" {
124→			body["description"] = input.Description
125→		}
126→		if input.DueString != "" {
127→			body["due_string"] = input.DueString
128→		}
129→		if input.Priority > 0 && input.Priority <= 4 {
130→			body["priority"] = input.Priority
131→		}
132→		if input.ProjectID != "" {
133→			body["project_id"] = input.ProjectID
134→		}
135→		if input.SectionID != "" {
136→			body["section_id"] = input.SectionID
137→		}
138→		if input.ParentID != "" {
139→			body["parent_id"] = input.ParentID
140→		}
141→		if len(input.Labels) > 0 {
142→			body["labels"] = input.Labels
143→		}
144→		if input.AssigneeID != "" {
145→			body["assignee_id"] = input.AssigneeID
146→		}
147→
148→		task, err := c.CreateTask(body)
149→		if err != nil {
150→			return nil, CreateTaskOutput{Success: false, Message: err.Error()}, err
151→		}
152→
153→		msg := fmt.Sprintf("Task created:\nTitle: %s", task.Content)
154→		if task.Description != "" {
155→			msg += fmt.Sprintf("\nDescription: %s", task.Description)
156→		}
157→		if task.Due != nil && task.Due.String != "" {
158→			msg += fmt.Sprintf("\nDue: %s", task.Due.String)
159→		}
160→		if task.Priority > 0 {
161→			msg += fmt.Sprintf("\nPriority: %d", task.Priority)
162→		}
163→
164→		return textResult(msg, false), CreateTaskOutput{Success: true, Message: msg}, nil
165→	})
166→
167→	mcp.AddTool(s, &mcp.Tool{
168→		Name:        "todoist_get_tasks",
169→		Description: "Get a list of tasks from Todoist with various filters",
170→	}, func(ctx context.Context, req *mcp.CallToolRequest, input GetTasksInput) (*mcp.CallToolResult, GetTasksOutput, error) {
171→		tasks, err := c.GetTasks(input.ProjectID, input.Filter)
172→		if err != nil {
173→			return nil, GetTasksOutput{}, err
174→		}
175→
176→		// Apply priority filter.
177→		if input.Priority > 0 && input.Priority <= 4 {
178→			filtered := tasks[:0]
179→			for _, t := range tasks {
180→				if t.Priority == input.Priority {
181→					filtered = append(filtered, t)
182→				}
183→			}
184→			tasks = filtered
185→		}
186→
187→		// Apply limit.
188→		limit := input.Limit
189→		if limit == 0 {
190→			limit = 10
191→		}
192→		if len(tasks) > limit {
193→			tasks = tasks[:limit]
194→		}
195→
196→		var msg string
197→		if len(tasks) == 0 {
198→			msg = "No tasks found matching the criteria"
199→		} else {
200→			var lines []string
201→			for _, t := range tasks {
202→				s := fmt.Sprintf("- %s", t.Content)
203→				if t.Description != "" {
204→					s += fmt.Sprintf("\n  Description: %s", t.Description)
205→				}
206→				if t.Due != nil && t.Due.String != "" {
207→					s += fmt.Sprintf("\n  Due: %s", t.Due.String)
208→				}
209→				if t.Priority > 0 {
210→					s += fmt.Sprintf("\n  Priority: %d", t.Priority)
211→				}
212→				lines = append(lines, s)
213→			}
214→			msg = strings.Join(lines, "\n\n")
215→		}
216→
217→		return textResult(msg, false), GetTasksOutput{Success: true, Message: msg}, nil
218→	})
219→
220→	mcp.AddTool(s, &mcp.Tool{
221→		Name:        "todoist_update_task",
222→		Description: "Update an existing task in Todoist by task_id or by searching by name",
223→	}, func(ctx context.Context, req *mcp.CallToolRequest, input UpdateTaskInput) (*mcp.CallToolResult, UpdateTaskOutput, error) {
224→		id, originalName, err := resolveTaskID(c, input.TaskID, input.TaskName)
225→		if err != nil {
226→			return nil, UpdateTaskOutput{Success: false, Message: err.Error()}, err
227→		}
228→		if id == "" {
229→			msg := fmt.Sprintf("Could not find a task matching \"%s\"", input.TaskName)
230→			return textResult(msg, true), UpdateTaskOutput{Success: false, Message: msg}, nil
231→		}
232→
233→		body := map[string]any{}
234→		if input.Content != "" {
235→			body["content"] = input.Content
236→		}
237→		if input.Description != "" {
238→			body["description"] = input.Description
239→		}
240→		if input.DueString != "" {
241→			body["due_string"] = input.DueString
242→		}
243→		if input.Priority > 0 && input.Priority <= 4 {
244→			body["priority"] = input.Priority
245→		}
246→		if len(input.Labels) > 0 {
247→			body["labels"] = input.Labels
248→		}
249→		if input.AssigneeID != "" {
250→			body["assignee_id"] = input.AssigneeID
251→		}
252→
253→		updated, err := c.UpdateTask(id, body)
254→		if err != nil {
255→			return nil, UpdateTaskOutput{Success: false, Message: err.Error()}, err
256→		}
257→
258→		label := originalName
259→		if label == "" {
260→			label = id
261→		}
262→		msg := fmt.Sprintf("Task \"%s\" updated:\nNew Title: %s", label, updated.Content)
263→		if updated.Description != "" {
264→			msg += fmt.Sprintf("\nNew Description: %s", updated.Description)
265→		}
266→		if updated.Due != nil && updated.Due.String != "" {
267→			msg += fmt.Sprintf("\nNew Due Date: %s", updated.Due.String)
268→		}
269→		if updated.Priority > 0 {
270→			msg += fmt.Sprintf("\nNew Priority: %d", updated.Priority)
271→		}
272→
273→		return textResult(msg, false), UpdateTaskOutput{Success: true, Message: msg}, nil
274→	})
275→
276→	mcp.AddTool(s, &mcp.Tool{
277→		Name:        "todoist_delete_task",
278→		Description: "Delete a task from Todoist by task_id or by searching by name",
279→	}, func(ctx context.Context, req *mcp.CallToolRequest, input DeleteTaskInput) (*mcp.CallToolResult, DeleteTaskOutput, error) {
280→		id, originalName, err := resolveTaskID(c, input.TaskID, input.TaskName)
281→		if err != nil {
282→			return nil, DeleteTaskOutput{Success: false, Message: err.Error()}, err
283→		}
284→		if id == "" {
285→			msg := fmt.Sprintf("Could not find a task matching \"%s\"", input.TaskName)
286→			return textResult(msg, true), DeleteTaskOutput{Success: false, Message: msg}, nil
287→		}
288→
289→		if err := c.DeleteTask(id); err != nil {
290→			return nil, DeleteTaskOutput{Success: false, Message: err.Error()}, err
291→		}
292→
293→		label := originalName
294→		if label == "" {
295→			label = id
296→		}
297→		msg := fmt.Sprintf("Successfully deleted task: \"%s\"", label)
298→		return textResult(msg, false), DeleteTaskOutput{Success: true, Message: msg}, nil
299→	})
300→
301→	mcp.AddTool(s, &mcp.Tool{
302→		Name:        "todoist_complete_task",
303→		Description: "Mark a task as complete by task_id or by searching by name",
304→	}, func(ctx context.Context, req *mcp.CallToolRequest, input CompleteTaskInput) (*mcp.CallToolResult, CompleteTaskOutput, error) {
305→		id, originalName, err := resolveTaskID(c, input.TaskID, input.TaskName)
306→		if err != nil {
307→			return nil, CompleteTaskOutput{Success: false, Message: err.Error()}, err
308→		}
309→		if id == "" {
310→			msg := fmt.Sprintf("Could not find a task matching \"%s\"", input.TaskName)
311→			return textResult(msg, true), CompleteTaskOutput{Success: false, Message: msg}, nil
312→		}
313→
314→		if err := c.CloseTask(id); err != nil {
315→			return nil, CompleteTaskOutput{Success: false, Message: err.Error()}, err
316→		}
317→
318→		label := originalName
319→		if label == "" {
320→			label = id
321→		}
322→		msg := fmt.Sprintf("Successfully completed task: \"%s\"", label)
323→		return textResult(msg, false), CompleteTaskOutput{Success: true, Message: msg}, nil
324→	})
325→
326→	mcp.AddTool(s, &mcp.Tool{
327→		Name:        "todoist_reopen_task",
328→		Description: "Reopen a completed task by task_id or by searching by name",
329→	}, func(ctx context.Context, req *mcp.CallToolRequest, input ReopenTaskInput) (*mcp.CallToolResult, ReopenTaskOutput, error) {
330→		id, originalName, err := resolveTaskID(c, input.TaskID, input.TaskName)
331→		if err != nil {
332→			return nil, ReopenTaskOutput{Success: false, Message: err.Error()}, err
333→		}
334→		if id == "" {
335→			msg := fmt.Sprintf("Could not find a task matching \"%s\"", input.TaskName)
336→			return textResult(msg, true), ReopenTaskOutput{Success: false, Message: msg}, nil
337→		}
338→
339→		if err := c.ReopenTask(id); err != nil {
340→			return nil, ReopenTaskOutput{Success: false, Message: err.Error()}, err
341→		}
342→
343→		label := originalName
344→		if label == "" {
345→			label = id
346→		}
347→		msg := fmt.Sprintf("Successfully reopened task: \"%s\"", label)
348→		return textResult(msg, false), ReopenTaskOutput{Success: true, Message: msg}, nil
349→	})
