 63→func registerGTDTools(s *mcp.Server, c *todoist.Client) {
 64→	// --- todoist_inbox_review ---
 65→	mcp.AddTool(s, &mcp.Tool{
 66→		Name:        "todoist_inbox_review",
 67→		Description: "Get all inbox tasks grouped by age (today, this week, older) for GTD inbox processing",
 68→	}, func(ctx context.Context, req *mcp.CallToolRequest, input InboxReviewInput) (*mcp.CallToolResult, InboxReviewOutput, error) {
 69→		// Find inbox project.
 70→		projects, err := c.GetProjects()
 71→		if err != nil {
 72→			return nil, InboxReviewOutput{}, err
 73→		}
 74→
 75→		var inboxID string
 76→		for _, p := range projects {
 77→			if p.IsInboxProject {
 78→				inboxID = p.ID
 79→				break
 80→			}
 81→		}
 82→		if inboxID == "" {
 83→			msg := "Could not find inbox project"
 84→			return textResult(msg, true), InboxReviewOutput{Success: false, Message: msg}, nil
 85→		}
 86→
 87→		tasks, err := c.GetTasks(inboxID, "")
 88→		if err != nil {
 89→			return nil, InboxReviewOutput{}, err
 90→		}
 91→
 92→		if len(tasks) == 0 {
 93→			msg := "Inbox is empty! Nothing to process."
 94→			return textResult(msg, false), InboxReviewOutput{Success: true, Message: msg}, nil
 95→		}
 96→
 97→		now := time.Now()
 98→		todayStart := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, now.Location())
 99→		weekAgo := todayStart.AddDate(0, 0, -7)
100→
101→		var todayTasks, weekTasks, olderTasks []models.Task
102→		for _, t := range tasks {
103→			switch {
104→			case t.CreatedAt.After(todayStart):
105→				todayTasks = append(todayTasks, t)
106→			case t.CreatedAt.After(weekAgo):
107→				weekTasks = append(weekTasks, t)
108→			default:
109→				olderTasks = append(olderTasks, t)
110→			}
111→		}
112→
113→		var sb strings.Builder
114→		fmt.Fprintf(&sb, "## Inbox Review (%d tasks)\n\n", len(tasks))
115→
116→		writeGroup := func(title string, group []models.Task) {
117→			fmt.Fprintf(&sb, "### %s (%d)\n", title, len(group))
118→			if len(group) == 0 {
119→				sb.WriteString("(none)\n")
120→			}
121→			for _, t := range group {
122→				fmt.Fprintf(&sb, "- %s (ID: %s)", t.Content, t.ID)
123→				if t.Priority > 1 {
124→					fmt.Fprintf(&sb, " [P%d]", t.Priority)
125→				}
126→				sb.WriteString("\n")
127→			}
128→			sb.WriteString("\n")
129→		}
130→
131→		writeGroup("Added Today", todayTasks)
132→		writeGroup("Added This Week", weekTasks)
133→		writeGroup("Older", olderTasks)
134→
135→		msg := sb.String()
136→		return textResult(msg, false), InboxReviewOutput{Success: true, Message: msg}, nil
137→	})
138→
139→	// --- todoist_weekly_review ---
140→	mcp.AddTool(s, &mcp.Tool{
141→		Name:        "todoist_weekly_review",
142→		Description: "Comprehensive weekly review: projects with task counts, overdue tasks, tasks with no due date",
143→	}, func(ctx context.Context, req *mcp.CallToolRequest, input WeeklyReviewInput) (*mcp.CallToolResult, WeeklyReviewOutput, error) {
144→		projects, err := c.GetProjects()
145→		if err != nil {
146→			return nil, WeeklyReviewOutput{}, err
147→		}
148→
149→		allTasks, err := c.GetTasks("", "")
150→		if err != nil {
151→			return nil, WeeklyReviewOutput{}, err
152→		}
153→
154→		// Count tasks per project.
155→		projectCounts := map[string]int{}
156→		for _, t := range allTasks {
157→			projectCounts[t.ProjectID]++
158→		}
159→
160→		// Overdue tasks.
161→		overdueTasks, err := c.GetTasks("", "overdue")
162→		if err != nil {
163→			overdueTasks = nil // non-fatal
164→		}
165→
166→		// Tasks with no due date.
167→		var noDueTasks []models.Task
168→		for _, t := range allTasks {
169→			if t.Due == nil {
170→				noDueTasks = append(noDueTasks, t)
171→			}
172→		}
173→
174→		var sb strings.Builder
175→		sb.WriteString("## Weekly Review\n\n")
176→
177→		// Projects summary.
178→		sb.WriteString("### Projects\n")
179→		for _, p := range projects {
180→			count := projectCounts[p.ID]
181→			tag := ""
182→			if p.IsInboxProject {
183→				tag = " [Inbox]"
184→			}
185→			fmt.Fprintf(&sb, "- %s%s: %d active tasks\n", p.Name, tag, count)
186→		}
187→		sb.WriteString("\n")
188→
189→		// Overdue.
190→		fmt.Fprintf(&sb, "### Overdue Tasks (%d)\n", len(overdueTasks))
191→		for _, t := range overdueTasks {
192→			due := ""
193→			if t.Due != nil {
194→				due = t.Due.Date
195→			}
196→			fmt.Fprintf(&sb, "- %s (due: %s, ID: %s)\n", t.Content, due, t.ID)
197→		}
198→		sb.WriteString("\n")
199→
200→		// No due date.
201→		fmt.Fprintf(&sb, "### No Due Date (%d)\n", len(noDueTasks))
202→		for _, t := range noDueTasks {
203→			fmt.Fprintf(&sb, "- %s (ID: %s)\n", t.Content, t.ID)
204→		}
205→
206→		msg := sb.String()
207→		return textResult(msg, false), WeeklyReviewOutput{Success: true, Message: msg}, nil
208→	})
209→
210→	// --- todoist_move_task ---
211→	mcp.AddTool(s, &mcp.Tool{
212→		Name:        "todoist_move_task",
213→		Description: "Move a task to a different project and/or section",
214→	}, func(ctx context.Context, req *mcp.CallToolRequest, input MoveTaskInput) (*mcp.CallToolResult, MoveTaskOutput, error) {
215→		id, originalName, err := resolveTaskID(c, input.TaskID, input.TaskName)
216→		if err != nil {
217→			return nil, MoveTaskOutput{Success: false, Message: err.Error()}, err
218→		}
219→		if id == "" {
220→			msg := fmt.Sprintf("Could not find a task matching \"%s\"", input.TaskName)
221→			return textResult(msg, true), MoveTaskOutput{Success: false, Message: msg}, nil
222→		}
223→
224→		body := map[string]any{}
225→		if input.ProjectID != "" {
226→			body["project_id"] = input.ProjectID
227→		}
228→		if input.SectionID != "" {
229→			body["section_id"] = input.SectionID
230→		}
231→
232→		_, err = c.UpdateTask(id, body)
233→		if err != nil {
234→			return nil, MoveTaskOutput{Success: false, Message: err.Error()}, err
235→		}
236→
237→		label := originalName
238→		if label == "" {
239→			label = id
240→		}
241→		msg := fmt.Sprintf("Successfully moved task \"%s\"", label)
242→		if input.ProjectID != "" {
243→			msg += fmt.Sprintf(" to project %s", input.ProjectID)
244→		}
245→		if input.SectionID != "" {
246→			msg += fmt.Sprintf(" section %s", input.SectionID)
247→		}
248→		return textResult(msg, false), MoveTaskOutput{Success: true, Message: msg}, nil
249→	})
250→
251→	// --- todoist_bulk_create_tasks ---
252→	mcp.AddTool(s, &mcp.Tool{
253→		Name:        "todoist_bulk_create_tasks",
254→		Description: "Create multiple tasks at once. Useful for batch processing from knowledge capture or project planning",
255→	}, func(ctx context.Context, req *mcp.CallToolRequest, input BulkCreateTasksInput) (*mcp.CallToolResult, BulkCreateTasksOutput, error) {
256→		var created, failed int
257→		var lines []string
258→
259→		for _, item := range input.Tasks {
260→			body := map[string]any{"content": item.Content}
261→			if item.Description != "" {
262→				body["description"] = item.Description
263→			}
264→			if item.DueString != "" {
265→				body["due_string"] = item.DueString
266→			}
267→			if item.Priority > 0 && item.Priority <= 4 {
268→				body["priority"] = item.Priority
269→			}
270→			if item.ProjectID != "" {
271→				body["project_id"] = item.ProjectID
272→			}
273→			if item.SectionID != "" {
274→				body["section_id"] = item.SectionID
275→			}
276→			if len(item.Labels) > 0 {
277→				body["labels"] = item.Labels
