func (c *Client) FindTaskByName(name string) (*models.Task, error) {
	tasks, err := c.GetTasks("", "")
	if err != nil {
		return nil, err
	}

	nameLower := strings.ToLower(name)

	// Prefer exact match first.
	for i := range tasks {
		if strings.ToLower(tasks[i].Content) == nameLower {
